def bis(f, lo, hi, n=200):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        fm = f(m)
        if (flo <= 0) == (fm <= 0):
            lo, flo = m, fm
        else:
            hi = m
    return (lo + hi) / 2

def skill():
    a = 3
    return 4**2 + (a*sqrt(2))**2

def standard():
    a = 3
    g = lambda x: a*math.sin(math.pi*x/4) - a*math.cos(math.pi*x/4)
    xs = [k*0.001 for k in range(0, 8000)]
    roots = [bis(g, x1, x2) for x1, x2 in zip(xs, xs[1:]) if g(x1)*g(x2) < 0]
    assert len(roots) == 2
    (x1, x2) = roots
    y1 = a*math.sin(math.pi*x1/4)
    y2 = a*math.sin(math.pi*x2/4)
    return round((x2 - x1)**2 + (y2 - y1)**2)

def unique():
    return [standard()]
